messages.content:
Write a single self-contained HTML file with a 3D animation using three.js. three.js r160 is available as an ES module at './three.module.js' -- import it with:
  import * as THREE from './three.module.js';
Scene: a low-poly 3D humanoid figure performs this exact cycle on a treadmill-style ground, side-on camera: stands still for 2 seconds, walks in place for 3 seconds (limbs swinging at walking pace), runs in place for 3 seconds (faster, larger limb swings, slight forward lean), then stands still again for 2 seconds. The 10-second cycle loops forever and must start immediately on load. Limb movement must clearly differ between walking and running. No external assets besides the three.js import. Output ONLY the HTML in one code block.

response.text:
```html
<!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0">
    <title>Low Poly Humanoid Animation</title>
    <style>
        body { margin: 0; overflow: hidden; background-color: #222; }
        canvas { display: block; }
    </style>
</head>
<body>

<!-- Import map for Three.js r160 -->
<script type="importmap">
    {
        "imports": {
            "three": "./three.module.js",
            "three/addons/": "./three/addons/"
        }
    }
</script>

<script type="module">
import * as THREE from './three.module.js';

// --- Configuration ---
const ANIMATION_DURATION = 10; // Total seconds
const STANDING_DURATION = 2;
const WALKING_DURATION = 3;
const RUNNING_DURATION = 3;

// --- Scene Setup ---
const scene = new THREE.Scene();
scene.background = new THREE.Color(0x87CEEB); // Sky blue
scene.fog = new THREE.Fog(0x87CEEB, 10, 50);

const camera = new THREE.PerspectiveCamera(60, window.innerWidth / window.innerHeight, 0.1, 100);
camera.position.set(0, 4, 8); // Side view, slightly elevated
camera.lookAt(0, 1, 0);

const renderer = new THREE.WebGLRenderer({ antialias: true });
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
document.body.appendChild(renderer.domElement);

// --- Lighting ---
const ambientLight = new THREE.AmbientLight(0xffffff, 0.6);
scene.add(ambientLight);

const dirLight = new THREE.DirectionalLight(0xffffff, 1.0);
dirLight.position.set(5, 10, 7);
dirLight.castShadow = true;
dirLight.shadow.mapSize.width = 1024;
dirLight.shadow.mapSize.height = 1024;
scene.add(dirLight);

// --- Ground (Treadmill) ---
const groundGeo = new THREE.PlaneGeometry(20, 20);
const groundMat = new THREE.MeshStandardMaterial({ color: 0x555555, roughness: 0.8 });
const ground = new THREE.Mesh(groundGeo, groundMat);
ground.rotation.x = -Math.PI / 2;
ground.receiveShadow = true;
scene.add(ground);

// Treadmill belt detail (moving grid)
const beltGeo = new THREE.PlaneGeometry(10, 20);
const beltMat = new THREE.MeshStandardMaterial({ color: 0x333333 });
const belt = new THREE.Mesh(beltGeo, beltMat);
belt.rotation.x = -Math.PI / 2;
belt.position.y = 0.01; // Slightly above ground
belt.receiveShadow = true;
scene.add(belt);

// --- Figure Construction ---
const figureGroup = new THREE.Group();
scene.add(figureGroup);

const matBody = new THREE.MeshStandardMaterial({ color: 0xffccaa }); // Skin tone
const matClothes = new THREE.MeshStandardMaterial({ color: 0x3366ff }); // Blue shirt
const matDark = new THREE.MeshStandardMaterial({ color: 0x222222 }); // Pants

// Helper to create a cylinder
function createCylinder(radiusTop, radiusBottom, height, segments, mat) {
    const geo = new THREE.CylinderGeometry(radiusTop, radiusBottom, height, 8);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
}

// Helper to create a sphere
function createSphere(radius, segments, mat) {
    const geo = new THREE.SphereGeometry(radius, 16, 16);
    const mesh = new THREE.Mesh(geo, mat);
    mesh.castShadow = true;
    mesh.receiveShadow = true;
    return mesh;
}

// 1. Torso
const torsoGroup = new THREE.Group();
const torsoMesh = createCylinder(0.35, 0.35, 1.0, 12, matBody);
torsoMesh.position.y = 0.5;
const shirtMesh = createCylinder(0.36, 0.36, 0.6, 12, matClothes);
shirtMesh.position.y = 0.3; // Overlap slightly
torsoGroup.add(torsoMesh);
torsoGroup.add(shirtMesh);
figureGroup.add(torsoGroup);

// 2. Head
const headMesh = createSphere(0.25, 16, matBody);
headMesh.position.y = 1.4;
torsoGroup.add(headMesh);

// 3. Arms (Shoulder Pivots)
const leftArmGroup = new THREE.Group();
leftArmGroup.position.set(-0.35, 0.8, 0);
const leftArmMesh = createCylinder(0.12, 0.08, 0.8, 8, matClothes);
leftArmMesh.position.y = -0.4;
leftArmGroup.add(leftArmMesh);
torsoGroup.add(leftArmGroup);

const rightArmGroup = new THREE.Group();
rightArmGroup.position.set(0.35, 0.8, 0);
const rightArmMesh = createCylinder(0.12, 0.08, 0.8, 8, matClothes);
rightArmMesh.position.y = -0.4;
rightArmGroup.add(rightArmMesh);
torsoGroup.add(rightArmGroup);

// 4. Legs (Hip Pivots)
const leftLegGroup = new THREE.Group();
leftLegGroup.position.set(-0.2, -0.5, 0);
const leftThigh = createCylinder(0.15, 0.12, 0.6, 8, matDark);
leftThigh.position.y = -0.3;
const leftShin = createCylinder(0.10, 0.08, 0.6, 8, matDark);
leftShin.position.y = -0.6;
leftLegGroup.add(leftThigh);
leftLegGroup.add(leftShin);
torsoGroup.add(leftLegGroup);

const rightLegGroup = new THREE.Group();
rightLegGroup.position.set(0.2, -0.5, 0);
const rightThigh = createCylinder(0.15, 0.12, 0.6, 8, matDark);
rightThigh.position.y = -0.3;
const rightShin = createCylinder(0.10, 0.08, 0.6, 8, matDark);
rightShin.position.y = -0.6;
rightLegGroup.add(rightThigh);
rightLegGroup.add(rightShin);
torsoGroup.add(rightLegGroup);

// --- Animation Logic ---
let time = 0;
let phase = 0; // 0: Stand, 1: Walk, 2: Run, 3: Stand
let beltSpeed = 0;

function updateAnimationState() {
    // Reset to start if animation loop completes or simply manage time
    // We use a global time variable for the cycle

    const now = performance.now() / 1000;

    // Reset if time exceeds duration (looping)
    if (time >= ANIMATION_DURATION) {
        time = 0;
    }

    // Determine current phase based on time
    if (time < STANDING_DURATION) {
        phase = 0; // Stand
    } else if (time < STANDING_DURATION + WALKING_DURATION) {
        phase = 1; // Walk
    } else if (time < STANDING_DURATION + WALKING_DURATION + RUNNING_DURATION) {
        phase = 2; // Run
    } else {
        phase = 3; // Stand
    }

    // Treadmill belt speed
    if (phase === 1) beltSpeed = 0.5; // Walk speed
    else if (phase === 2) beltSpeed = 1.5; // Run speed
    else beltSpeed = 0;

    // Update belt visual
    belt.position.z += beltSpeed * 0.1;
    if (belt.position.z > 10) belt.position.z = -10;

    // Normalize time within the current phase for smoother interpolation
    let phaseTime = 0;
    if (phase === 0) {
        phaseTime = (time / STANDING_DURATION) * Math.PI; // 0 to PI
    } else if (phase === 1) {
        phaseTime = ((time - STANDING_DURATION) / WALKING_DURATION) * Math.PI;
    } else if (phase === 2) {
        phaseTime = ((time - STANDING_DURATION - WALKING_DURATION) / RUNNING_DURATION) * Math.PI;
    } else {
        phaseTime = (time - STANDING_DURATION - WALKING_DURATION - RUNNING_DURATION) / 2; // 0 to 1
    }

    updateLimbMovement(phaseTime, phase);
}

function updateLimbMovement(t, phase) {
    const walkAmp = 0.6; // Amplitude of swing
    const runAmp = 1.2;  // Amplitude of swing (larger)
    const walkSpeed = 1.5; // Angular velocity
    const runSpeed = 3.5;  // Angular velocity

    // --- Arms ---
    // Left Arm
    let angleL = 0;
    if (phase !== 0) {
        angleL = Math.sin(t * (phase === 1 ? walkSpeed : runSpeed)) * (phase === 1 ? walkAmp : runAmp);
    }
    leftArmGroup.rotation.z = angleL;

    // Right Arm
    let angleR = 0;
    if (phase !== 0) {
        angleR = Math.sin(t * (phase === 1 ? walkSpeed : runSpeed) + Math.PI) * (phase === 1 ? walkAmp : runAmp);
    }
    rightArmGroup.rotation.z = angleR;

    // --- Legs ---
    // Left Leg
    let legL = 0;
    if (phase !== 0) {
        legL = Math.sin(t * (phase === 1 ? walkSpeed : runSpeed)) * (phase === 1 ? walkAmp : runAmp);
    }
    leftLegGroup.rotation.x = legL;

    // Right Leg
    let legR = 0;
    if (phase !== 0) {
        legR = Math.sin(t * (phase === 1 ? walkSpeed : runSpeed) + Math.PI) * (phase === 1 ? walkAmp : runAmp);
    }
    rightLegGroup.rotation.x = legR;

    // --- Running Specifics (Lean) ---
    if (phase === 2) {
        // Slight forward lean during run
        torsoGroup.rotation.z = Math.sin(t * runSpeed * 2) * 0.1; 
    } else {
        torsoGroup.rotation.z = 0;
    }
}

// --- Animation Loop ---
function animate() {
    requestAnimationFrame(animate);

    updateAnimationState();
    renderer.render(scene, camera);
}

// Handle Resize
window.addEventListener('resize', () => {
    camera.aspect = window.innerWidth / window.innerHeight;
    camera.updateProjectionMatrix();
    renderer.setSize(window.innerWidth, window.innerHeight);
});

// Start
animate();

</script>
</body>
</html>
```
